import json,pathlib,zipfile
root=pathlib.Path('/mnt/data/player_reference'); p=json.load(open('/mnt/data/parameter_reference/project.json')); names=['Player','Player body','Player out','Died/Pipie','Power up','Phone Controls','Levels','Enemy','Boss','Dragon','Ball','Final Boss','Stage']; targets=[t for t in p['targets'] if t['name'] in names]; (root/'player_source.json').write_text(json.dumps({'targets':targets,'extensions':p.get('extensions')},indent=2)); flow=pathlib.Path('/mnt/data/parameter_reference/SCRIPT_FLOW.txt').read_text(); sections=flow.split('===== '); (root/'script_flow.txt').write_text('\n===== '.join(s for s in sections if s.split(' =====')[0] in names));
lines=['# Player behavior: native port specification','Static analysis of original Dorfplatformer9 project. Block IDs below refer to player_source.json. All coordinates use positive Y upward.','## Active call sequence','Player Tick (QV) -> Tick (q+) -> Animate Cat (p#) -> Keys (qs) and vertical collision sdfghj.- (rE). All four custom procedures have no arguments and warp=true. Tick probes +3 Y, selects PLAYER TEME from Teme if Y world=0 else teme, calls Animate Cat, then subtracts 3 Y. Player Tick decrements J B by 1 before Tick, then sets scale 25 for N else 50, checks Y < -300, sets ghost 100. When Play=0 resets sx,sy,Scroll x and position (-100,100), hides, stops script.','## Input','Walk[1]=right: axis>0 or (D and not A) or (Right and not Left) or touch[2]. Walk[2]=left: inverse equivalents and touch[1]. Walk[3]=W or Up or pad1 button1 or touch[3]. Walk[4]=OR of right sources minus OR of left sources. If S or Down or touch[4], powerup != N and theme !=4, clear all four. Keys runs AFTER jump counter check and before gravity: jump uses prior Walk state, vertical landing uses current Walk.','## Movement (Animate Cat p#)','If x<-240 set x=-220 and sx=18. Select mask 2, mask 3 if Down/touch[4]/touch Levels, override with mask 4 if theme=4; store costume in _______Cos. If Scroll x>999999999999999 set Day=3/3,E=5,broadcast Win. If jump>0 and FAll<1 increment jump by 0.1 and if jump<1.8 set sy=14/0.77. If prior Walk[3] false reset jump=0. FAll += 1/60; Fall +=1; Keys; show; select mask 5; subtract gravity (1 if backdrop #3, else 1.96); restore mask. Theme 4 clamps sy to >=-4 and sets sy=4 if Walk[3]. Call vertical collision, clear Set = 0. sx/=2.5; if axis==0 add 2*Walk[1]-2*Walk[2], else add 2*axis; sx*=2. fame+=abs(round(sx))/6; if rounded speed zero and theme !=4 reset fame=0. Horizontal loop abs(round(sx)) times, step sign(sx), check Levels, switch to probe costume 5, reverse step, restore saved mask, check collision and either reapply step or set Set = 0=1. After loop if Set = 0==1 set sx=0. Preserve source ordering and empty branches.','## Vertical collision (rE)','Store Y in thread variable variable. Restore saved mask. Repeat round(abs(sy)) times; step sign(sy) if rounded magnitude nonzero. On touching Levels set Set = 0=1, switch mask 5, reverse step if still touching, restore mask. Condition operator_not has missing operand (Ro); under ordinary Scratch empty Boolean semantics it is true. If sy>0 set jump=99,sy=0; else FAll=0,Fall=0,jump=0,sy=0; if current Walk[3] play Jump for N else Jump2, set jump=1. Clear Set = 0 and stop this script. Confirm stop behavior in warp procedure against TurboWarp.','## Camera','Scroll: if Play=1 and Final Boss=0 add sprite x to Scroll x, set x=0, if Scroll x<0 add it back to x and clamp Scroll x=0; export Cam x, My y, my x pos. The x>0 if block has EMPTY body; do not incorrectly gate the following statements. Scroll X imports Cam x into Scroll x, sets x=0, applies same negative clamp and exports coordinates, subtracts 3 Y. Final Boss bypasses horizontal scrolling.','## Events','Create: Win leve=0,Cam x=0,sy=0,fall=0,position(-100,100),show,Scroll x=0,hide. Died: Pause=1, broadcast Still, pitch=90, play Cymbal Echo until done, clear effects, Win leve=0,Cam x=0,sy=0,Powerup=B,fall=0,position(-100,100),show,Y world=0,Scroll x=0,hide,broadcast Lave,broadcast and wait Restart Level,Pause=0,stop sounds. Does not explicitly reset sx or Fall/FAll/jump here. Yump: sy=32 and sound Kill mopps. Up: stop other scripts, if y<-179 hide/delete clone; Set = 0=0. Lave: stop other scripts, hide Time monitor and self. Win: Win leve=1 and stop other scripts. Toi died: go to Died/Pipie.','## Visual body','Scale 25 N,50 otherwise. Color 0 or -54 for F if a____SS=0, else increment 5 each visual loop. Body Y=My y+11.875*(size/25)-1, X=my x pos. Fall>1 selects airborne costume 7, theme4 instead round(fame mod 1)+9 and stops script. Otherwise face Walk[4]*90 when nonzero and walking costume fame mod 5+1. Crouch Down/touch[4] if Teme!=4 and powerup!=N: subtract 7 Y, select dorf bewoner-B2. Preserve fractional costume selection semantics.','## Power and damage','Power Up: N->B->F; F with a____SS=0 sets a____SS=1 and plays sound. Power down: F->B->N->Died; N branch waits 9s then DAMAGE=0. Body flashes 67 times, ghost 100/0 with 0.02s wait each, DAMAGE=1 then 0. Other handlers also write DAMAGE: scheduling must be tested. Color contact blocks #3e0080 and #ffa9a9 exist but are detached top-level stacks with no event hat; do not automatically treat them as active collision rules. Enemy/boss interactions in source appendix.','## Timing and fidelity','Player physics uses per-tick constants, not delta time. Levels loop broadcasts Move all then Player Tick after pause/transition checks, waits 0. Nominal 60 tick interpretation comes from FAll +=1/60, not proof of actual fixed scheduler rate. Do not silently rescale to seconds. Preserve Scratch rounding (negative half ties toward positive infinity), 1-based arrays, costume selection, missing operands, event reentrancy and clone semantics. Detached editor stacks are retained in source but are not automatically executed. No runtime comparison performed.','## Player local variables and saved values'];
for t in targets:
 if t['name'] in ['Player','Player body','Player out','Died/Pipie']:
  lines.append('\n### '+t['name']); lines.append('| Name | Saved value | ID |\n|---|---|---|');
  for k,(n,v,*_) in t['variables'].items():lines.append(f'| {n} | {v} | `{k.replace("|","&#124;")}` |');
  lines.append('\nCostumes (1-based):');
  for i,c in enumerate(t['costumes'],1):lines.append(f'- {i}: {c["name"]}, center ({c["rotationCenterX"]}, {c["rotationCenterY"]}), bitmap resolution {c.get("bitmapResolution",1)}, asset {c.get("md5ext")}')
(root/'PLAYER_BEHAVIOR.md').write_text('\n\n'.join(lines));
with zipfile.ZipFile('/mnt/data/Dorfplatformer9_player_reference.zip','w',zipfile.ZIP_DEFLATED) as z:
 for n in ['PLAYER_BEHAVIOR.md','player_source.json','script_flow.txt']:z.write(root/n,n)
